using Object=winrt::Windows::Data::Json::JsonObject;using Array=winrt::Windows::Data::Json::JsonArray;using Value=winrt::Windows::Data::Json::JsonValue;using Type=winrt::Windows::Data::Json::JsonValueType;
inline void put(const Object& object,const wchar_t* key,std::string_view value){object.SetNamedValue(key,Value::CreateStringValue(winrt::to_hstring(value)));}
inline std::string text(const Object& object,const wchar_t* key,std::size_t maximum=4096){const auto value=winrt::to_string(object.GetNamedString(key,L""));if(value.size()>maximum||value.find('\0')!=std::string::npos||!local_file::utf8(value))throw std::invalid_argument("Invalid bounded background-host text");return value;}
inline std::string guid(std::string value){GUID parsed{};if(value.size()!=38||FAILED(CLSIDFromString(winrt::to_hstring(value).c_str(),&parsed)))throw std::invalid_argument("Invalid background-host GUID");wchar_t canonical[40]{};StringFromGUID2(parsed,canonical,40);auto result=winrt::to_string(canonical);for(auto& ch:result)if(ch>='A'&&ch<='Z')ch=static_cast<char>(ch+32);for(auto& ch:value)if(ch>='A'&&ch<='Z')ch=static_cast<char>(ch+32);if(result!=value)throw std::invalid_argument("Noncanonical background-host GUID");return result;}
inline std::string new_guid(){GUID value{};winrt::check_hresult(CoCreateGuid(&value));wchar_t raw[40]{};StringFromGUID2(value,raw,40);return guid(winrt::to_string(raw));}
inline void keys(const Object& object,std::initializer_list<const wchar_t*> allowed){for(const auto& item:object){bool found{};for(const auto key:allowed)if(item.Key()==key){found=true;break;}if(!found)throw std::invalid_argument("Unsupported background-host command field");}}
inline std::uint64_t integer(const Object& object,const wchar_t* name){const auto value=object.GetNamedNumber(name,0);if(!std::isfinite(value)||value<0||std::floor(value)!=value||value>9007199254740991.0)throw std::invalid_argument("Invalid background-host sequence");return static_cast<std::uint64_t>(value);}
struct Key {std::string thread,provider;bool operator==(const Key&)const=default;std::string name()const{return thread+"."+provider;}};
inline Key checked(Key value){value.thread=guid(value.thread);static const std::set<std::string> providers{"codex","claude","opencode","cursor","grok","antigravity"};if(!providers.contains(value.provider))throw std::invalid_argument("Unsupported hosted provider");return value;}
inline Object encode(const Key& value){Object result;put(result,L"thread",value.thread);put(result,L"provider",value.provider);return result;}
inline Key key(const Object& object){keys(object,{L"thread",L"provider"});return checked({text(object,L"thread",38),text(object,L"provider",32)});}
struct Launch {std::filesystem::path executable,cwd,profile_directory;std::vector<std::wstring> arguments;std::string session_id,profile_id{"default"},saved_profile_id,saved_account_scope,instructions;};
inline void validate(const Launch& value){if(!local_file::local_path(value.executable)||!local_file::local_path(value.cwd)||(!value.profile_directory.empty()&&!local_file::local_path(value.profile_directory))||value.arguments.size()>64||value.session_id.size()>4096||value.instructions.size()>512*1024||value.profile_id.size()>80||value.saved_profile_id.size()>80||value.saved_account_scope.size()>64)throw std::invalid_argument("Invalid bounded hosted launch");for(const auto& arg:value.arguments)if(arg.size()>32768||arg.find(L'\0')!=std::wstring::npos)throw std::invalid_argument("Invalid hosted launch argument");for(const auto* str:{&value.session_id,&value.profile_id,&value.saved_profile_id,&value.saved_account_scope,&value.instructions})if(str->find('\0')!=std::string::npos||!local_file::utf8(*str))throw std::invalid_argument("Invalid hosted launch text");}
inline Object encode(const Launch& value){validate(value);Object result;put(result,L"executable",winrt::to_string(value.executable.wstring()));put(result,L"cwd",winrt::to_string(value.cwd.wstring()));put(result,L"profile_directory",winrt::to_string(value.profile_directory.wstring()));Array arguments;for(const auto& arg:value.arguments)arguments.Append(Value::CreateStringValue(arg));result.SetNamedValue(L"arguments",arguments);put(result,L"session_id",value.session_id);put(result,L"profile_id",value.profile_id);put(result,L"saved_profile_id",value.saved_profile_id);put(result,L"saved_account_scope",value.saved_account_scope);put(result,L"instructions",value.instructions);return result;}
inline Launch launch(const Object& object){keys(object,{L"executable",L"cwd",L"profile_directory",L"arguments",L"session_id",L"profile_id",L"saved_profile_id",L"saved_account_scope",L"instructions"});Launch value;value.executable=winrt::to_hstring(text(object,L"executable",32768)).c_str();value.cwd=winrt::to_hstring(text(object,L"cwd",32768)).c_str();value.profile_directory=winrt::to_hstring(text(object,L"profile_directory",32768)).c_str();const auto args=object.GetNamedArray(L"arguments",Array{});if(args.Size()>64)throw std::invalid_argument("Too many hosted arguments");for(const auto& arg:args)value.arguments.emplace_back(arg.GetString());value.session_id=text(object,L"session_id");value.profile_id=text(object,L"profile_id",80);value.saved_profile_id=text(object,L"saved_profile_id",80);value.saved_account_scope=text(object,L"saved_account_scope",64);value.instructions=text(object,L"instructions",512*1024);validate(value);return value;}
inline Object encode(const CodexTurn& value){if(value.text.size()>512*1024||value.image_paths.size()>64)throw std::invalid_argument("Hosted input exceeds its bound");Object object;put(object,L"text",value.text);put(object,L"cwd",value.cwd);put(object,L"model",value.model);put(object,L"effort",value.effort);put(object,L"service_tier",value.service_tier);object.SetNamedValue(L"plan",Value::CreateBooleanValue(value.plan));object.SetNamedValue(L"full_access",Value::CreateBooleanValue(value.access==AgentAccess::full_access));Array images;for(const auto& path:value.image_paths){if(path.size()>32768)throw std::invalid_argument("Hosted image path exceeds its bound");images.Append(Value::CreateStringValue(winrt::to_hstring(path)));}object.SetNamedValue(L"images",images);return object;}
inline CodexTurn turn(const Object& object){keys(object,{L"text",L"cwd",L"model",L"effort",L"service_tier",L"plan",L"full_access",L"images"});CodexTurn value;value.text=text(object,L"text",512*1024);value.cwd=text(object,L"cwd",32768);if(!value.cwd.empty()&&!local_file::local_path(winrt::to_hstring(value.cwd).c_str()))throw std::invalid_argument("Invalid hosted working folder");value.model=text(object,L"model",512);value.effort=text(object,L"effort",80);value.service_tier=text(object,L"service_tier",80);value.plan=object.GetNamedBoolean(L"plan",false);value.access=object.GetNamedBoolean(L"full_access",false)?AgentAccess::full_access:AgentAccess::approval;const auto images=object.GetNamedArray(L"images",Array{});if(images.Size()>64)throw std::invalid_argument("Too many hosted images");for(const auto& path:images){const auto str=winrt::to_string(path.GetString());if(str.size()>32768||str.find('\0')!=std::string::npos||!local_file::local_path(winrt::to_hstring(str).c_str()))throw std::invalid_argument("Invalid hosted image path");value.image_paths.push_back(str);}return value;}
inline Object encode(const SessionEvent& event){if(static_cast<int>(event.kind)<0||static_cast<int>(event.kind)>static_cast<int>(SessionEvent::Kind::usage)||event.id.size()>4096||event.text.size()>1024*1024||event.detail.size()>1024*1024)throw std::invalid_argument("Hosted event exceeds its bound");Object result;result.SetNamedValue(L"kind",Value::CreateNumberValue(static_cast<int>(event.kind)));put(result,L"id",event.id);put(result,L"text",event.text);put(result,L"detail",event.detail);return result;}
inline SessionEvent event(const Object& object){const auto kind=integer(object,L"kind");if(kind>static_cast<unsigned>(SessionEvent::Kind::usage))throw std::invalid_argument("Unsupported hosted event kind");return{static_cast<SessionEvent::Kind>(kind),text(object,L"id"),text(object,L"text",1024*1024),text(object,L"detail",1024*1024)};}
struct LoggedEvent {std::string epoch;std::uint64_t sequence{};SessionEvent value;std::string delivery_id;};
inline Object encode(const LoggedEvent& value){Object result;put(result,L"epoch",value.epoch);result.SetNamedValue(L"sequence",Value::CreateNumberValue(static_cast<double>(value.sequence)));result.SetNamedValue(L"event",encode(value.value));put(result,L"delivery_id",value.delivery_id);return result;}
inline LoggedEvent logged(const Object& object){return{guid(text(object,L"epoch",38)),integer(object,L"sequence"),event(object.GetNamedObject(L"event")),text(object,L"delivery_id",38)};}
inline std::string launch_fingerprint(const Launch& value){return local_file::sha256(winrt::to_string(encode(value).Stringify()));}
inline Object encode(const AgentQueuedTurn& value){Object object;put(object,L"id",guid(value.id));object.SetNamedValue(L"turn",encode(value.turn));return object;}
inline AgentQueuedTurn queued(const Object& object){return{guid(text(object,L"id",38)),turn(object.GetNamedObject(L"turn"))};}
struct SessionInfo {
    Key key;std::string epoch;bool live{},busy{},review{};std::uint64_t last{},acknowledged{};std::vector<SessionEvent> prompts;
    std::string profile_id,account_scope,launch_fingerprint;std::vector<AgentQueuedTurn> queued;bool queue_paused{true};std::string models;
    bool snapshots_included{true};std::uint64_t queued_count{},models_sequence{};
};
inline void fingerprint(const std::string& value){if(!value.empty()&&(value.size()!=64||value.find_first_not_of("0123456789abcdef")!=std::string::npos))throw std::invalid_argument("Invalid nonsecret host binding fingerprint");}
inline Object encode(const SessionInfo& info){
    if(info.profile_id.size()>80||info.profile_id.find('\0')!=std::string::npos||info.queued_count>64||info.models_sequence>info.last||(info.snapshots_included&&info.queued_count!=info.queued.size())||(!info.snapshots_included&&(!info.queued.empty()||!info.prompts.empty()||!info.models.empty())))throw std::invalid_argument("Invalid hosted session snapshot");fingerprint(info.account_scope);fingerprint(info.launch_fingerprint);if(info.models.size()>512*1024)throw std::invalid_argument("Hosted model catalog exceeds its snapshot bound");if(!info.models.empty())static_cast<void>(Object::Parse(winrt::to_hstring(info.models)));
    Object value;value.SetNamedValue(L"key",encode(info.key));put(value,L"epoch",info.epoch);for(const auto& pair:{std::pair{L"live",info.live},{L"busy",info.busy},{L"review",info.review},{L"queue_paused",info.queue_paused},{L"snapshots_included",info.snapshots_included}})value.SetNamedValue(pair.first,Value::CreateBooleanValue(pair.second));value.SetNamedValue(L"last",Value::CreateNumberValue(static_cast<double>(info.last)));value.SetNamedValue(L"acknowledged",Value::CreateNumberValue(static_cast<double>(info.acknowledged)));put(value,L"profile_id",info.profile_id);put(value,L"account_scope",info.account_scope);put(value,L"launch_fingerprint",info.launch_fingerprint);put(value,L"models",info.models);value.SetNamedValue(L"models_sequence",Value::CreateNumberValue(static_cast<double>(info.models_sequence)));value.SetNamedValue(L"queued_count",Value::CreateNumberValue(static_cast<double>(info.queued_count)));
    Array prompts;std::size_t prompt_bytes{};for(const auto& prompt:info.prompts){const auto encoded=encode(prompt);prompt_bytes+=winrt::to_string(encoded.Stringify()).size();if(prompt_bytes>512*1024)throw std::invalid_argument("Hosted prompt snapshots exceed their transport bound");prompts.Append(encoded);}value.SetNamedValue(L"prompts",prompts);
    if(info.queued.size()>64)throw std::invalid_argument("Hosted queue count exceeds its bound");Array queue;std::set<std::string> ids;std::size_t bytes{};for(const auto& input:info.queued){if(!ids.insert(guid(input.id)).second)throw std::invalid_argument("Duplicate hosted queue identifier");const auto encoded=encode(input);bytes+=winrt::to_string(encoded.Stringify()).size();if(bytes>1024*1024)throw std::invalid_argument("Hosted queue exceeds its serialized snapshot bound");queue.Append(encoded);}value.SetNamedValue(L"queued",queue);if(winrt::to_string(value.Stringify()).size()>2*1024*1024)throw std::invalid_argument("Hosted session snapshots exceed their transport bound");return value;
}
inline SessionInfo info(const Object& object){SessionInfo value{key(object.GetNamedObject(L"key")),guid(text(object,L"epoch",38)),object.GetNamedBoolean(L"live",false),object.GetNamedBoolean(L"busy",false),object.GetNamedBoolean(L"review",false),integer(object,L"last"),integer(object,L"acknowledged"),{}};if(value.acknowledged>value.last)throw std::invalid_argument("Invalid hosted acknowledgment");const auto prompts=object.GetNamedArray(L"prompts",Array{});if(prompts.Size()>64)throw std::invalid_argument("Too many hosted prompts");for(const auto& prompt:prompts)value.prompts.push_back(event(prompt.GetObject()));value.profile_id=text(object,L"profile_id",80);value.account_scope=text(object,L"account_scope",64);value.launch_fingerprint=text(object,L"launch_fingerprint",64);if(value.launch_fingerprint.empty())value.launch_fingerprint=text(object,L"launch_hash",64);value.queue_paused=object.GetNamedBoolean(L"queue_paused",true);value.snapshots_included=object.GetNamedBoolean(L"snapshots_included",true);value.models=text(object,L"models",512*1024);value.models_sequence=integer(object,L"models_sequence");const auto queue=object.GetNamedArray(L"queued",Array{});if(queue.Size()>64)throw std::invalid_argument("Too many hosted queued inputs");for(const auto& input:queue)value.queued.push_back(queued(input.GetObject()));value.queued_count=object.HasKey(L"queued_count")?integer(object,L"queued_count"):value.queued.size();(void)encode(value);return value;}
inline SessionInfo summary(SessionInfo value){value.prompts.clear();value.queued.clear();value.models.clear();value.snapshots_included=false;return value;}
enum class Operation{start,send,steer,queue,respond,interrupt,shutdown,list,poll,acknowledge,review,retire,delivery_status,status,refresh_models,remove_queue,edit_queue,pause_queue,resume_queue,shutdown_host};
inline const wchar_t* operation_name(Operation value){switch(value){case Operation::start:return L"start";case Operation::send:return L"send";case Operation::steer:return L"steer";case Operation::queue:return L"queue";case Operation::respond:return L"respond";case Operation::interrupt:return L"interrupt";case Operation::shutdown:return L"shutdown";case Operation::list:return L"list";case Operation::poll:return L"poll";case Operation::acknowledge:return L"acknowledge";case Operation::review:return L"review";case Operation::retire:return L"retire";case Operation::delivery_status:return L"delivery_status";case Operation::status:return L"status";case Operation::refresh_models:return L"refresh_models";case Operation::remove_queue:return L"remove_queue";case Operation::edit_queue:return L"edit_queue";case Operation::pause_queue:return L"pause_queue";case Operation::resume_queue:return L"resume_queue";case Operation::shutdown_host:return L"shutdown_host";}throw std::invalid_argument("Unsupported host operation");}
inline bool global(Operation value){return value==Operation::list||value==Operation::retire||value==Operation::shutdown_host;}
inline bool input_operation(Operation value){return value==Operation::send||value==Operation::steer||value==Operation::queue||value==Operation::edit_queue;}
inline bool delivery_operation(Operation value){return value==Operation::send||value==Operation::steer||value==Operation::queue||value==Operation::edit_queue||value==Operation::remove_queue||value==Operation::delivery_status;}
struct Command {std::string id{new_guid()};Operation operation{Operation::list};Key key;std::string epoch,delivery_id;Launch launch;CodexTurn input;std::string prompt_id,result;std::uint64_t sequence{};};
inline Object encode(const Command& command){Object value;put(value,L"id",guid(command.id));put(value,L"operation",winrt::to_string(operation_name(command.operation)));if(global(command.operation))return value;value.SetNamedValue(L"key",encode(checked(command.key)));put(value,L"epoch",guid(command.epoch));if(command.operation==Operation::start)value.SetNamedValue(L"launch",encode(command.launch));if(delivery_operation(command.operation))put(value,L"delivery_id",guid(command.delivery_id));if(input_operation(command.operation))value.SetNamedValue(L"input",encode(command.input));if(command.operation==Operation::respond){put(value,L"prompt_id",command.prompt_id);put(value,L"result",command.result);}if(command.operation==Operation::poll||command.operation==Operation::acknowledge)value.SetNamedValue(L"sequence",Value::CreateNumberValue(static_cast<double>(command.sequence)));return value;}
inline Command command(const Object& value){keys(value,{L"id",L"operation",L"key",L"epoch",L"launch",L"delivery_id",L"input",L"prompt_id",L"result",L"sequence"});Command result;result.id=guid(text(value,L"id",38));const auto operation=text(value,L"operation",32);bool found{};for(int n=0;n<=static_cast<int>(Operation::shutdown_host);++n)if(operation==winrt::to_string(operation_name(static_cast<Operation>(n)))){result.operation=static_cast<Operation>(n);found=true;break;}if(!found)throw std::invalid_argument("Unsupported host command");if(global(result.operation))return result;result.key=key(value.GetNamedObject(L"key"));result.epoch=guid(text(value,L"epoch",38));if(result.operation==Operation::start)result.launch=launch(value.GetNamedObject(L"launch"));if(delivery_operation(result.operation))result.delivery_id=guid(text(value,L"delivery_id",38));if(input_operation(result.operation))result.input=turn(value.GetNamedObject(L"input"));if(result.operation==Operation::respond){result.prompt_id=text(value,L"prompt_id");result.result=text(value,L"result",512*1024);}if(result.operation==Operation::poll||result.operation==Operation::acknowledge)result.sequence=integer(value,L"sequence");return result;}
